<script setup>
import {ref,computed} from 'vue';import KnowledgeRecognitionReview from '@/components/business/knowledge/KnowledgeRecognitionReview.vue';import KnowledgePageViewer from '@/components/business/knowledge/KnowledgePageViewer.vue';import KnowledgeTestPanel from '@/components/business/knowledge/KnowledgeTestPanel.vue';
const page=ref('89'),mode=ref('table'),readonly=ref(false),broken=ref(false),width=ref('');const data=ref({});async function refresh(){for(const p of ['89','90','75'])data.value[p]=await(await fetch('/fixture/'+p)).json()}await refresh();const current=computed(()=>data.value[page.value]);
</script><template><main :style="width?{width:width+'px'}:{}"><h1>阶段2 · B端真实组件 / 隔离协议Fixture</h1><p class="banner">人工源图基线，仅模拟审核与问答协议。HTTP/SSE由本机Fixture服务产生；未连接正式Backend、数据库、队列或OSS。</p><nav><button v-for="p in ['89','90','75']" @click="page=p">印刷页 {{p}}</button><button @click="mode='table';refresh()">已确认表格</button><button @click="mode='review'">识别审核</button><button @click="mode='qa'">知识库测试</button><button @click="readonly=!readonly">{{readonly?'切回可编辑':'切换只读'}}</button><button @click="broken=!broken">{{broken?'恢复图片':'模拟图片失效'}}</button><button @click="width='768'">768px 容器</button><button @click="width='1280'">1280px 容器</button><button @click="width=''">完整宽度</button></nav><KnowledgeRecognitionReview v-if="mode==='review'" :key="page+readonly" document-id="fixture-document" :version-id="'fixture-'+page" :version-editable="!readonly" @refresh="refresh"/><KnowledgeTestPanel v-else-if="mode==='qa'" :key="page" :version-id="'fixture-'+page"/><KnowledgePageViewer v-else :key="page" :page-id="'fixture-page-'+page" :render-model="current.renderModel" :confirmed-structured-data="current.data" :page-label="page" :page-image-url="broken?'/expired.png':'/original-'+page+'.png'" :highlights="current.matches"/></main></template><style>body{margin:0;background:#f4f6fa;font-family:Arial,'Microsoft YaHei',sans-serif;color:#253247}main{max-width:1440px;padding:20px;margin:auto;box-sizing:border-box}h1{font-size:20px}.banner{padding:12px;background:#fff4d8;color:#5f4b12}nav{display:flex;flex-wrap:wrap;gap:8px;margin-block:12px}nav button{padding:8px;cursor:pointer}</style>